SELECT set_config('test.uid','10000000-0000-0000-0000-000000000001',false);
DO $test$
DECLARE item uuid; req uuid; same uuid; movement uuid; unknown_item uuid; unknown_request uuid; unknown_movement uuid;
 d uuid:='20000000-0000-0000-0000-000000000001'; w uuid:='40000000-0000-0000-0000-000000000001'; f uuid:='30000000-0000-0000-0000-000000000001';
 ids uuid[]:=ARRAY['80000000-0000-0000-0000-000000000001'::uuid,'80000000-0000-0000-0000-000000000002'::uuid]; token uuid:=gen_random_uuid();
BEGIN
 INSERT INTO stock_items(domain_id,code,name,category,unit) VALUES(d,'KNOWN','Engrais','engrais','kg') RETURNING id INTO item;
 INSERT INTO stock_movements(stock_item_id,warehouse_id,movement_type,quantity,unit_cost,movement_date) VALUES(item,w,'entree',100,10,current_date);
 req:=submit_allocated_stock_exit(w,item,10,current_date,NULL,'TEST',f,ids,token);
 same:=submit_allocated_stock_exit(w,item,10,current_date,NULL,'TEST',f,ids,token);
 PERFORM test_assert(req=same,'submission retry must be idempotent');
 PERFORM test_assert((SELECT current_qty=100 FROM warehouse_stocks WHERE stock_item_id=item),'submission does not consume');
 PERFORM test_reject(format('SELECT execute_stock_exit_request(%L)',req),'approuvée');
 UPDATE stock_exit_requests SET status='approuvee' WHERE id=req;
 movement:=execute_stock_exit_request(req);
 PERFORM test_assert(execute_stock_exit_request(req)=movement,'execution retry must be idempotent');
 PERFORM test_assert((SELECT current_qty=90 FROM warehouse_stocks WHERE stock_item_id=item),'stock deducted once');
 PERFORM test_assert((SELECT count(*)=2 AND sum(amount)=100 FROM cost_entries WHERE source_stock_movement_id=movement),'two charges with exact total');
 PERFORM test_assert((SELECT amount=25 FROM cost_entries WHERE source_stock_movement_id=movement AND greenhouse_id='60000000-0000-0000-0000-000000000001'),'area allocation 25 percent');
 PERFORM test_reject(format('SELECT review_inventory_consumption_multi(%L,NULL,11,%L)',movement,'Facture test'),'non encore imputée');
 INSERT INTO stock_items(domain_id,code,name,category,unit) VALUES(d,'UNKNOWN','Sans prix','engrais','kg') RETURNING id INTO unknown_item;
 INSERT INTO stock_movements(stock_item_id,warehouse_id,movement_type,quantity,movement_date) VALUES(unknown_item,w,'entree',100,current_date);
 unknown_request:=submit_allocated_stock_exit(w,unknown_item,8,current_date,'Test sans prix',NULL,f,ids,gen_random_uuid());
 UPDATE stock_exit_requests SET status='approuvee' WHERE id=unknown_request;
 unknown_movement:=execute_stock_exit_request(unknown_request);
 PERFORM test_assert(NOT EXISTS(SELECT 1 FROM cost_entries WHERE source_stock_movement_id=unknown_movement),'unknown price waits for review');
 PERFORM test_assert((stock_consumption_allocation_context(unknown_movement)->>'fixed')::boolean,'targets retained');
 PERFORM review_inventory_consumption_multi(unknown_movement,NULL,3,'Facture test');
 PERFORM test_assert((SELECT count(*)=2 AND sum(amount)=24 FROM cost_entries WHERE source_stock_movement_id=unknown_movement),'review generates two costs');
 PERFORM test_assert((SELECT current_qty=92 FROM warehouse_stocks WHERE stock_item_id=unknown_item),'review does not deduct stock again');
 INSERT INTO stock_movements(stock_item_id,warehouse_id,movement_type,quantity,movement_date) VALUES(unknown_item,w,'sortie',4,current_date) RETURNING id INTO movement;
 PERFORM review_inventory_consumption_multi(movement,ids,2,'Ancienne sortie');
 PERFORM test_assert((SELECT count(*)=2 AND sum(amount)=8 FROM cost_entries WHERE source_stock_movement_id=movement),'legacy direct movement multi review');
 PERFORM test_reject(format('SELECT stock_allocation_targets(%L,%L,%L::uuid[])',d,f,ARRAY[ids[1],ids[1]]),'distinctes');
 PERFORM test_reject(format('SELECT stock_allocation_targets(%L,%L,%L::uuid[])',d,'30000000-0000-0000-0000-000000000002',ids),'Ferme active');
 PERFORM test_reject(format('SELECT submit_allocated_stock_exit(%L,%L,1,current_date,%L,NULL,%L,%L::uuid[],%L)',w,item,'Different',f,ids,token),'autre contenu');
 req:=submit_allocated_stock_exit(w,item,1,current_date,NULL,NULL,f,ids,gen_random_uuid());
 INSERT INTO approval_requests(domain_id,process_code,entity_id,status) VALUES(d,'stock_exit',req,'soumise');
 PERFORM set_config('test.uid','10000000-0000-0000-0000-000000000002',true);
 PERFORM test_reject(format('SELECT cancel_stock_exit_request(%L)',req),'Seul');
 PERFORM set_config('test.uid','10000000-0000-0000-0000-000000000001',true);
 PERFORM cancel_stock_exit_request(req);
 PERFORM cancel_stock_exit_request(req);
 PERFORM test_assert((SELECT status='annulee' AND cancelled_by=auth.uid() AND cancelled_at IS NOT NULL FROM stock_exit_requests WHERE id=req),'author cancellation tracked');
 PERFORM test_assert((SELECT status='annulee' FROM approval_requests WHERE entity_id=req),'approval cancelled');
 PERFORM test_assert((SELECT current_qty=90 FROM warehouse_stocks WHERE stock_item_id=item),'cancellation leaves stock intact');
 PERFORM test_reject(format('SELECT execute_stock_exit_request(%L)',req),'approuvée');
 PERFORM test_reject(format('SELECT cancel_stock_exit_request(%L)',unknown_request),'avant validation');
 req:=submit_allocated_stock_exit(w,item,5,current_date,NULL,NULL,f,ids,gen_random_uuid());
 PERFORM test_reject(format('SELECT review_stock_exit_request(%L,true,NULL)',req),'distinct du demandeur');
 PERFORM set_config('test.uid','10000000-0000-0000-0000-000000000002',true);
 PERFORM review_stock_exit_request(req,true,NULL);
 PERFORM review_stock_exit_request(req,true,NULL);
 PERFORM test_assert((SELECT status='executee' AND approved_by=auth.uid() AND stock_movement_id IS NOT NULL FROM stock_exit_requests WHERE id=req),'approval immediately executes');
 PERFORM test_assert((SELECT current_qty=85 FROM warehouse_stocks WHERE stock_item_id=item),'approval deducted once');
 PERFORM test_assert((SELECT sum(amount)=50 FROM cost_entries WHERE source_stock_movement_id=(SELECT stock_movement_id FROM stock_exit_requests WHERE id=req)),'approval generates costs immediately');
 PERFORM set_config('test.uid','10000000-0000-0000-0000-000000000001',true);
 req:=submit_allocated_stock_exit(w,item,1000,current_date,NULL,NULL,f,ids,gen_random_uuid());
 PERFORM set_config('test.uid','10000000-0000-0000-0000-000000000002',true);
 PERFORM test_reject(format('SELECT review_stock_exit_request(%L,true,NULL)',req),'Stock insuffisant');
 PERFORM test_assert((SELECT status='soumise' AND approved_by IS NULL AND stock_movement_id IS NULL FROM stock_exit_requests WHERE id=req),'failed deduction rolls approval back');
 PERFORM set_config('test.uid','10000000-0000-0000-0000-000000000002',true);
 PERFORM set_config('test.uid','10000000-0000-0000-0000-000000000001',true);
 req:=submit_warehouse_stock_exit(w,item,1,current_date,'Ancienne demande',NULL);
 UPDATE stock_exit_requests SET campaign_id='50000000-0000-0000-0000-000000000001',greenhouse_id='60000000-0000-0000-0000-000000000001' WHERE id=req;
 PERFORM set_config('test.uid','10000000-0000-0000-0000-000000000002',true);
 PERFORM review_stock_exit_request(req,true,NULL);
 PERFORM test_assert((SELECT status='executee' AND stock_movement_id IS NOT NULL FROM stock_exit_requests WHERE id=req),'legacy approval also executes');
 UPDATE stock_exit_requests SET status='approuvee' WHERE id=req;
 PERFORM execute_stock_exit_request(req);
 PERFORM test_assert((SELECT current_qty=84 FROM warehouse_stocks WHERE stock_item_id=item),'existing linked movement must not deduct again');
 PERFORM test_assert((SELECT sum(amount)=10 FROM cost_entries WHERE source_stock_movement_id=(SELECT stock_movement_id FROM stock_exit_requests WHERE id=req)),'legacy cost preserved');
 PERFORM test_reject(format('SELECT get_stock_allocation_catalog(%L)',d),'interdite');
END $test$;
SELECT 'Multi-serres SQL assertions passed' AS result;
